/* ═══════════════════════════════════════════════════════════════════
   2 · CONSTANTS
   ═══════════════════════════════════════════════════════════════════ */

/** Cutoff categories, in ascending order. Index 0 = lowest band. */
const BMI_CATEGORIES = [
  'Severely Wasted',
  'Wasted',
  'Normal',
  'Overweight',
  'Obese'
];

/** Height-for-age categories. */
const HFA_STUNTED = 'Stunted';
const HFA_NORMAL  = 'Normal';
const HFA_TALL    = 'Tall';

/* ═══════════════════════════════════════════════════════════════════
   3 · INTERNALS
   ═══════════════════════════════════════════════════════════════════ */

/** Normalise any sex representation to 'M' or 'F'. Returns null if unknown. */
function _sexChar(sex) {
  if (sex == null) return null;
  const c = String(sex).trim().charAt(0).toUpperCase();
  return (c === 'M' || c === 'F') ? c : null;
}

/** Clamp a number to a range. */
function _clamp(n, lo, hi) { return Math.max(lo, Math.min(hi, n)); }

/** Linear interpolation between two numbers. */
function _lerp(a, b, t) { return a + (b - a) * t; }

/**
 * Find the two rows that bracket the given month value, plus the
 * interpolation weight `t` (0 → at rows[lo], 1 → at rows[hi]).
 */
function _bracket(months) {
  const rows = TABLE.rows;
  if (!rows.length) return null;

  const m = _clamp(months, TABLE.minMonths, TABLE.maxMonths);

  if (m <= rows[0].months)                    return { lo: 0,               hi: 0,               t: 0 };
  if (m >= rows[rows.length - 1].months)      return { lo: rows.length - 1, hi: rows.length - 1, t: 0 };

  // Binary search for the largest index where rows[i].months <= m
  let lo = 0, hi = rows.length - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (rows[mid].months <= m) lo = mid;
    else                       hi = mid;
  }
  const t = (m - rows[lo].months) / (rows[hi].months - rows[lo].months);
  return { lo, hi, t };
}

/**
 * Return the interpolated value array for a (section, sex, months) triple.
 * section = 'bmi' | 'hfa'  ·  sex = 'M' | 'F'
 */
function _interpolate(section, sex, months) {
  const br = _bracket(months);
  if (!br) return null;

  const a = TABLE.rows[br.lo][section][sex];
  const b = TABLE.rows[br.hi][section][sex];
  if (!a || !b) return null;
  if (a.length !== b.length) return null;

  const out = new Array(a.length);
  for (let i = 0; i < a.length; i++) out[i] = _lerp(a[i], b[i], br.t);
  return out;
}

/**
 * Convert a flat list of paired boundary values into midpoints.
 * Example: [12.0, 12.1, 12.9, 13.0]  →  [12.05, 12.95]
 *
 * The original data encodes each boundary as two adjacent numbers
 * (lower and upper edges of a transition band). Taking the midpoint
 * gives us one clean cutoff per classification transition.
 */
function _pairMidpoints(arr) {
  const out = [];
  for (let i = 0; i + 1 < arr.length; i += 2) {
    out.push((arr[i] + arr[i + 1]) / 2);
  }
  return out;
}

/* ═══════════════════════════════════════════════════════════════════
   4 · PUBLIC API
   ═══════════════════════════════════════════════════════════════════ */

/** True once the reference tables are embedded. Always true in this build. */
export const WHO_LOADED = Array.isArray(TABLE.rows) && TABLE.rows.length > 0;

/**
 * Number of complete months between a birth date and a reference date.
 * Returns null if either date is missing or invalid.
 *
 * @param {string|Date} birthDate     Birth date (ISO string or Date)
 * @param {string|Date} [referenceDate=new Date()]
 * @returns {number|null}
 */
export function ageInMonths(birthDate, referenceDate) {
  if (!birthDate) return null;

  const b = birthDate instanceof Date ? birthDate : new Date(birthDate);
  const r = referenceDate == null
    ? new Date()
    : (referenceDate instanceof Date ? referenceDate : new Date(referenceDate));

  if (isNaN(b.getTime()) || isNaN(r.getTime())) return null;

  let months = (r.getFullYear() - b.getFullYear()) * 12
             + (r.getMonth()    - b.getMonth());

  // Incomplete calendar month → not yet counted
  if (r.getDate() < b.getDate()) months -= 1;

  return months < 0 ? null : months;
}

/**
 * Classify a BMI value against the WHO BMI-for-age reference.
 * Returns one of:
 *   'Severely Wasted' | 'Wasted' | 'Normal' | 'Overweight' | 'Obese'
 * or null if the input is invalid or the tables are unavailable.
 *
 * @param {number} bmi     BMI in kg/m²
 * @param {string} sex     "M"/"Male" or "F"/"Female"
 * @param {number} months  Age in months
 * @returns {string|null}
 */
export function classifyBMI(bmi, sex, months) {
  const s = _sexChar(sex);
  if (!s) return null;
  if (bmi == null || !isFinite(bmi) || bmi <= 0) return null;
  if (months == null || !isFinite(months)) return null;

  const values = _interpolate('bmi', s, months);
  if (!values || values.length < 8) return null;

  // 4 cutoffs = 5 categories (Severely Wasted … Obese)
  const cutoffs = _pairMidpoints(values);

  if (bmi < cutoffs[0]) return BMI_CATEGORIES[0];
  if (bmi < cutoffs[1]) return BMI_CATEGORIES[1];
  if (bmi < cutoffs[2]) return BMI_CATEGORIES[2];
  if (bmi < cutoffs[3]) return BMI_CATEGORIES[3];
  return BMI_CATEGORIES[4];
}

/**
 * Classify a height against the WHO height-for-age reference.
 * Returns 'Stunted' | 'Normal' | 'Tall', or null if invalid.
 *
 * The reference table stores boundary heights in metres; this function
 * accepts height in centimetres (as main.ts passes h*100) and converts
 * internally.
 *
 * @param {number} heightCm  Height in centimetres
 * @param {string} sex       "M"/"Male" or "F"/"Female"
 * @param {number} months    Age in months
 * @returns {string|null}
 */
export function classifyHeightForAge(heightCm, sex, months) {
  const s = _sexChar(sex);
  if (!s) return null;
  if (heightCm == null || !isFinite(heightCm) || heightCm <= 0) return null;
  if (months == null || !isFinite(months)) return null;

  const values = _interpolate('hfa', s, months);
  if (!values || values.length < 6) return null;

  // 3 pairs → 3 midpoints (approx. -3SD, -2SD, +2SD in metres)
  const cutoffs = _pairMidpoints(values);

  // Cutoffs are metres; convert input to metres for the comparison.
  const hM = heightCm / 100;

  // Use the -2SD boundary as the Stunted threshold and the +2SD boundary
  // as the Tall threshold. Anything between the two is Normal.
  if (hM < cutoffs[1]) return HFA_STUNTED;
  if (hM > cutoffs[2]) return HFA_TALL;
  return HFA_NORMAL;
}

/* ═══════════════════════════════════════════════════════════════════
   5 · DEFAULT EXPORT (optional convenience)
   ═══════════════════════════════════════════════════════════════════ */
export default {
  WHO_LOADED,
  ageInMonths,
  classifyBMI,
  classifyHeightForAge
};